// ValidationError 是稳定的结构化校验错误;Path 指向首个失败位置。
type ValidationError struct {
	Path    string
	Rule    string
	Message string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("%s: %s (%s)", e.Path, e.Message, e.Rule)
}

func validationError(path, rule, format string, args ...any) error {
	return &ValidationError{Path: path, Rule: rule, Message: fmt.Sprintf(format, args...)}
}

// ValidateFrameSize 按完整 UTF-8 帧字节数执行硬上限;maxBytes<=0 时使用契约默认值。
func ValidateFrameSize(frame []byte, maxBytes int64) error {
	if maxBytes <= 0 {
		maxBytes = DefaultMaxMsgBytes
	}
	if int64(len(frame)) > maxBytes {
		return validationError("$", "maxBytes", "帧为 %d 字节,上限 %d", len(frame), maxBytes)
	}
	return nil
}

// ValidateKindBody 校验已知字段并忽略未知加法字段;cmd/event 还会下钻 args/data schema。
func ValidateKindBody(kind Kind, raw json.RawMessage) error {
	name, ok := bodySchemas[kind]
	if !ok {
		return validationError("$", "kind", "未知 kind %q", kind)
	}
	if err := validateRaw(name, raw); err != nil {
		return err
	}
	switch kind {
	case KindCmd:
		var body CmdBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		if err := validateCommandSemantics(body); err != nil {
			return err
		}
		return rebaseValidationError(ValidatePrimitiveArgs(body.Name, body.Ver, body.Args), "$.args")
	case KindEvent:
		var body EventBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		return rebaseValidationError(ValidateEventData(string(body.Name), body.Data), "$.data")
	default:
		return nil
	}
}

func ValidatePrimitiveArgs(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	return validateRaw(s.Args, raw)
}

func ValidatePrimitiveData(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	return validateRaw(s.Data, raw)
}

func ValidateEventData(name string, raw json.RawMessage) error {
	s, ok := eventSchemas[name]
	if !ok {
		return validationError("$", "event", "未知事件 %q", name)
	}
	return validateRaw(s, raw)
}

func validateCommandSemantics(body CmdBody) error {
	meta, ok := Primitives[body.Name]
	if !ok || meta.Ver == 0 {
		return validationError("$.name", "primitive", "未知或未激活原语 %q", body.Name)
	}
	if meta.Ver != body.Ver {
		return validationError("$.ver", "version", "原语 %q 需要版本 %d,收到 %d", body.Name, meta.Ver, body.Ver)
	}
	isDebug := strings.HasPrefix(body.Name, "debug.")
	if !isDebug && body.Context == nil && !meta.ContextOptionalBeforeBinding {
		return validationError("$.context", "required", "除绑定前探测外,非 debug 原语必须携带 context")
	}
	if meta.Class == ClassEffectful {
		if body.IdemKey == "" {
			return validationError("$.idemKey", "required", "effectful 原语必须携带 idemKey")
		}
	} else if body.IdemKey != "" {
		return validationError("$.idemKey", "forbidden", "readonly/intrusive 原语禁止携带 idemKey")
	}
	if meta.LeaseMs > 0 && body.LeaseMs == 0 {
		return validationError("$.leaseMs", "required", "原语 %q 必须携带租约", body.Name)
	}
	if meta.LeaseMs == 0 && body.LeaseMs != 0 {
		return validationError("$.leaseMs", "forbidden", "原语 %q 未启用租约", body.Name)
	}
	if !isDebug && meta.Class != ClassReadonly {
		if body.Context == nil || body.Context.ExpectedPrincipalFingerprint == "" {
			return validationError("$.context.expectedPrincipalFingerprint", "required", "intrusive/effectful 原语必须携带期望账号指纹")
		}
	}
	return nil
}

func validateRaw(schemaName string, raw json.RawMessage) error {
	if len(raw) == 0 {
		return validationError("$", "json", "空 JSON")
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var value any
	if err := dec.Decode(&value); err != nil {
		return validationError("$", "json", "%v", err)
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		return validationError("$", "json", "JSON 后存在额外内容")
	}
	spec, ok := schemaTypes[schemaName]
	if !ok {
		return validationError("$", "schema", "未知 schema %q", schemaName)
	}
	return validateSpec(spec, value, "$")
}

func validateSpec(spec schemaSpec, value any, path string) error {
	if value == nil {
		if spec.Nullable || spec.Type == "any" {
			return nil
		}
		return validationError(path, "nullable", "不允许 null")
	}
	if spec.Ref != "" {
		target, ok := schemaTypes[spec.Ref]
		if !ok {
			return validationError(path, "schema", "未知引用 %q", spec.Ref)
		}
		return validateSpec(target, value, path)
	}
	if spec.MaxJSONBytes > 0 {
		encoded, err := json.Marshal(value)
		if err != nil {
			return validationError(path, "json", "%v", err)
		}
		if len(encoded) > spec.MaxJSONBytes {
			return validationError(path, "maxJsonBytes", "JSON 为 %d 字节,上限 %d", len(encoded), spec.MaxJSONBytes)
		}
	}
	switch spec.Type {
	case "any":
		return nil
	case "boolean":
		v, ok := value.(bool)
		if !ok {
			return validationError(path, "type", "需要 boolean")
		}
		if spec.Const != nil && v != *spec.Const {
			return validationError(path, "const", "必须为 %t", *spec.Const)
		}
		return nil
	case "string":
		v, ok := value.(string)
		if !ok {
			return validationError(path, "type", "需要 string")
		}
		runes := utf8.RuneCountInString(v)
		if runes < spec.MinLength {
			return validationError(path, "minLength", "长度 %d 小于下限 %d", runes, spec.MinLength)
		}
		if spec.MaxLength > 0 && runes > spec.MaxLength {
			return validationError(path, "maxLength", "长度 %d 超过上限 %d", runes, spec.MaxLength)
		}
		if spec.MaxBytes > 0 && len([]byte(v)) > spec.MaxBytes {
			return validationError(path, "maxBytes", "UTF-8 为 %d 字节,上限 %d", len([]byte(v)), spec.MaxBytes)
		}
		if spec.EnumRef != "" && !stringAllowed(schemaEnums[spec.EnumRef], v) {
			return validationError(path, "enum", "%q 不在 %s 内", v, spec.EnumRef)
		}
		return nil
	case "int", "int64":
		n, ok := value.(json.Number)
		if !ok {
			return validationError(path, "type", "需要整数")
		}
		v, err := n.Int64()
		if err != nil {
			return validationError(path, "type", "需要 int64 范围内整数")
		}
		if v < -9007199254740991 || v > 9007199254740991 {
			return validationError(path, "safeInteger", "整数超出跨 Go/TS 安全范围")
		}
		if spec.Minimum != nil && v < *spec.Minimum {
			return validationError(path, "minimum", "%d 小于下限 %d", v, *spec.Minimum)
		}
		if spec.Maximum != nil && v > *spec.Maximum {
			return validationError(path, "maximum", "%d 超过上限 %d", v, *spec.Maximum)
		}
		return nil
	case "array":
		v, ok := value.([]any)
		if !ok {
			return validationError(path, "type", "需要 array")
		}
		if len(v) < spec.MinItems {
			return validationError(path, "minItems", "元素数 %d 小于下限 %d", len(v), spec.MinItems)
		}
		if spec.MaxItems > 0 && len(v) > spec.MaxItems {
			return validationError(path, "maxItems", "元素数 %d 超过上限 %d", len(v), spec.MaxItems)
		}
		if spec.Items == nil {
			return validationError(path, "schema", "array 缺 items")
		}
		for i, item := range v {
			if err := validateSpec(*spec.Items, item, fmt.Sprintf("%s[%d]", path, i)); err != nil {
				return err
			}
		}
		return nil
	case "object":
		v, ok := value.(map[string]any)
		if !ok {
			return validationError(path, "type", "需要 object")
		}
		for name, field := range spec.Fields {
			fv, exists := v[name]
			if !exists {
				if !field.Optional {
					return validationError(path+"."+name, "required", "缺少必填字段")
				}
				continue
			}
			if err := validateSpec(field, fv, path+"."+name); err != nil {
				return err
			}
		}
		// 未知字段故意不遍历:主版本内 must-ignore。
		for _, rule := range spec.Rules {
			if err := validateSchemaRule(rule, v, path); err != nil {
				return err
			}
		}
		return nil
	default:
		return validationError(path, "schema", "未知 schema type %q", spec.Type)
	}
}

func validateSchemaRule(rule schemaRule, values map[string]any, path string) error {
	actual, ok := values[rule.WhenField]
	if !ok || !anyAllowed(rule.Equals, actual) {
		return nil
	}
	nonNull := func(field string) bool { value, exists := values[field]; return exists && value != nil }
	switch rule.Kind {
	case "requiredWhen":
		if !nonNull(rule.Field) {
			return validationError(path+"."+rule.Field, "requiredWhen", "条件成立时字段必填且非 null")
		}
	case "forbiddenWhen":
		if nonNull(rule.Field) {
			return validationError(path+"."+rule.Field, "forbiddenWhen", "条件成立时字段必须缺省或 null")
		}
	case "exactlyOneWhen":
		count := 0
		for _, field := range rule.Fields {
			if nonNull(field) {
				count++
			}
		}
		if count != 1 {
			return validationError(path, "exactlyOneWhen", "条件成立时 %v 必须恰有一个非 null", rule.Fields)
		}
	case "atLeastOneTrueWhen":
		matched := false
		for _, field := range rule.Fields {
			if value, ok := values[field].(bool); ok && value {
				matched = true
			}
		}
		if !matched {
			return validationError(path, "atLeastOneTrueWhen", "条件成立时 %v 至少一个必须为 true", rule.Fields)
		}
	case "allFalseWhen":
		for _, field := range rule.Fields {
			if value, ok := values[field].(bool); !ok || value {
				return validationError(path+"."+field, "allFalseWhen", "条件成立时必须为 false")
			}
		}
	default:
		return validationError(path, "schema", "未知规则 %q", rule.Kind)
	}
	return nil
}

func stringAllowed(values []string, value string) bool {
	for _, candidate := range values {
		if candidate == value {
			return true
		}
	}
	return false
}

func anyAllowed(values []any, value any) bool {
	for _, candidate := range values {
		if reflect.DeepEqual(candidate, value) {
			return true
		}
	}
	return false
}

func rebaseValidationError(err error, base string) error {
	if err == nil {
		return nil
	}
	var validation *ValidationError
	if !errorsAsValidation(err, &validation) {
		return err
	}
	path := base
	if validation.Path != "$" {
		path += strings.TrimPrefix(validation.Path, "$")
	}
	return &ValidationError{Path: path, Rule: validation.Rule, Message: validation.Message}
}

func errorsAsValidation(err error, target **ValidationError) bool {
	validation, ok := err.(*ValidationError)
	if ok {
		*target = validation
	}
	return ok
}
